// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon } from 'lucide-react'

import { Btn, DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { BULK, CAPTIONS, V4, V7 } from './script'

const TABS = ['UUID v4', 'UUID v7', 'NanoID']
const HEX = '0123456789abcdef'

const build: Build = ({ tl, q, qa, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const tab = (index: number) => {
    move(`tab-${index}`)
    click(`tab-${index}`)
    tl.to(
      qa('tab'),
      { backgroundColor: 'rgba(255,255,255,0)', color: '#8b8b9a', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`tab-${index}`),
      { backgroundColor: 'rgba(99,102,241,0.22)', color: '#f4f4f6', duration: 0.15 },
      '<',
    )
  }

  step(0)
  tab(0)
  move('generate')
  click('generate')
  scramble('v4', V4, { at: '<', duration: 0.9, chars: HEX })
  tl.fromTo(
    q('ripple'),
    { scale: 0.5, opacity: 0.6 },
    { scale: 1.3, opacity: 0, duration: 0.6 },
    '<0.7',
  )

  step(1, '+=0.4')
  tab(1)
  tl.to(q('v4'), { opacity: 0, duration: 0.2 }, '<')
  tl.set(q('v7'), { opacity: 1 })
  scramble('v7', V7, { at: '<', duration: 0.9, chars: HEX })
  scramble('kind', 'Time-ordered · sorts by creation', { at: '<0.3', duration: 0.6 })

  step(2, '+=0.5')
  move('bulk')
  click('bulk')
  tl.to(q('single'), { opacity: 0.35, duration: 0.2 }, '<')
  qa('bulk-row').forEach((row, index) =>
    scramble(row, BULK[index], { at: index === 0 ? '<0.1' : '<0.08', duration: 0.6, chars: HEX }),
  )

  step(3, '+=0.5')
  tl.to(q('single'), { opacity: 1, duration: 0.2 }, '<')
  move('check', { ax: 0.15 })
  click('check')
  type('check-text', V4, { speed: 0.008 })
  tl.fromTo(
    q('valid'),
    { opacity: 0, scale: 0.8 },
    { opacity: 1, scale: 1, duration: 0.35, ease: 'back.out(2.5)' },
  )
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="ID Toolkit generating UUID v4 and v7 values, a bulk batch, and validating a UUID"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div className="flex gap-1 rounded-lg border border-line bg-canvas/60 p-0.5">
            {TABS.map((name, index) => (
              <span
                key={name}
                data-d={`tab tab-${index}`}
                className="flex-1 rounded-md py-1 text-center text-[10.5px] text-muted"
              >
                {name}
              </span>
            ))}
          </div>
          <div
            data-d="single"
            className="relative h-[74px] rounded-xl border border-line-strong bg-canvas/80 px-3 py-3 font-mono"
          >
            <span
              data-d="ripple"
              className="absolute inset-0 rounded-xl border-2 border-[var(--accent)] opacity-0"
            />
            <p data-d="v4" className="text-[13px] tracking-tight text-ink" />
            <p
              data-d="v7"
              className="absolute left-3 top-3 text-[13px] tracking-tight text-ink opacity-0"
            />
            <p data-d="kind" className="absolute bottom-2.5 left-3 text-[9.5px] text-muted">
              Random · 122 bits
            </p>
          </div>
          <div className="flex gap-2">
            <Btn d="generate" primary>
              Generate
            </Btn>
            <Btn d="bulk">Bulk × 5</Btn>
          </div>
          <div className="min-h-0 flex-1 space-y-0.5 overflow-hidden rounded-xl border border-line bg-canvas/60 px-3 py-2 font-mono text-[10.5px] text-ink-soft">
            {BULK.map((_, index) => (
              <p key={index} data-d="bulk-row" className="h-[16px]" />
            ))}
          </div>
          <div className="flex items-center gap-2">
            <Label>Validate</Label>
            <div
              data-d="check"
              className="flex h-7 min-w-0 flex-1 items-center truncate rounded-lg border border-line bg-canvas/80 px-2 font-mono text-[10px]"
            >
              <span data-d="check-text" className="truncate" />
            </div>
            <span
              data-d="valid"
              className="flex items-center gap-1 rounded-full bg-emerald/15 px-2 py-1 text-[10px] text-emerald opacity-0"
            >
              <CheckIcon className="size-3" /> UUID v4
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
